    // Carousel
    (function() {
      const track = document.getElementById('carouselInner');
      const slides = track.querySelectorAll('.carousel-slide');
      const dots = document.querySelectorAll('.carousel-dot');
      let current = 0;
      let touchStartX = 0;
      let autoTimer;

      function goTo(index) {
        current = (index + slides.length) % slides.length;
        track.style.transform = `translateX(-${current * 100}%)`;
        dots.forEach((d, i) => d.classList.toggle('active', i === current));
      }

      document.getElementById('carouselPrev').addEventListener('click', () => { clearInterval(autoTimer); goTo(current - 1); });
      document.getElementById('carouselNext').addEventListener('click', () => { clearInterval(autoTimer); goTo(current + 1); });
      dots.forEach(d => d.addEventListener('click', () => { clearInterval(autoTimer); goTo(+d.dataset.index); }));

      // Touch / swipe
      const outer = document.getElementById('carouselTrack');
      outer.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; }, { passive: true });
      outer.addEventListener('touchend', e => {
        const dx = e.changedTouches[0].clientX - touchStartX;
        if (Math.abs(dx) > 50) { clearInterval(autoTimer); goTo(dx < 0 ? current + 1 : current - 1); }
      }, { passive: true });

      autoTimer = setInterval(() => goTo(current + 1), 4500);
    })();
  </script>
