    display: flex;
    flex-direction: column;
    position: fixed;
    top: calc(var(--nav-height) + 36px);
    left: 0; right: 0;
    background: oklch(6% 0.01 0 / 0.98);
    border-bottom: 1px solid var(--border);
    padding: 1.5rem 2rem 2rem;
    gap: 0.25rem;
