.page-hero-inner { position: relative; z-index: 1; }
.page-hero .section-label { display: block; margin-bottom: 1.5rem; }
.page-hero h1 { font-size: clamp(2.5rem, 7vw, 6rem); margin-bottom: 1.5rem; }
.page-hero p {
  font-size: 1.125rem;
  color: var(--text-muted);
