.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.newsletter-text .section-label { display: block; margin-bottom: 1rem; }
.newsletter-text h2 { font-size: clamp(1.8rem, 3vw, 2.8rem); margin-bottom: 1rem; }
.newsletter-text p { color: var(--text-muted); }
.newsletter-form { display: flex; flex-direction: column; gap: 1rem; }
.form-group { position: relative; }
.form-input {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 1rem;
  padding: 1rem 1.25rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}
.form-input::placeholder { color: var(--text-subtle); }
.form-input:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 3px oklch(52% 0.26 25 / 0.15);
}
.form-input.error { border-color: oklch(60% 0.22 20); }
.form-error {
  font-size: 0.8rem;
  color: oklch(65% 0.22 25);
  margin-top: 0.4rem;
  min-height: 1.2em;
  display: none;
}
.form-error.visible { display: block; }
.form-success {
  font-size: 0.875rem;
  color: oklch(70% 0.18 150);
  display: none;
}
.form-success.visible { display: block; }
@media (max-width: 768px) {
  .newsletter-inner { grid-template-columns: 1fr; gap: 2rem; }
}

/* ── Footer ── */
.footer {
  background: oklch(5.5% 0.01 0);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 4rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}
.footer-logo {
  font-family: var(--font-head);
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: white;
}
.footer-logo span { color: var(--red); }
.footer-tagline {
  color: var(--text-subtle);
  font-size: 0.875rem;
  margin-top: 0.75rem;
  font-style: italic;
}
.footer-nav-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.footer-col h4 {
  font-family: var(--font-head);
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
  text-transform: uppercase;
}
.footer-col ul { list-style: none; }
.footer-col ul li { margin-bottom: 0.6rem; }
.footer-col ul a {
  color: var(--text-subtle);
  font-size: 0.875rem;
  transition: color var(--transition);
}
.footer-col ul a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.footer-bottom p { color: var(--text-subtle); font-size: 0.8rem; }

/* ── Country Selector ── */
.footer-country { position: relative; }
.country-selector {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-family: var(--font-body);
  font-size: 0.8rem;
  padding: 0.5rem 0.9rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all var(--transition);
}
.country-selector:hover { border-color: var(--border-light); color: white; }
.country-arrow { opacity: 0.6; font-size: 0.7rem; }
.country-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
  min-width: 180px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
  transition: all var(--transition);
}
.country-dropdown.open {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}
.country-option {
  display: block;
  width: 100%;
  background: none;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-body);
  font-size: 0.85rem;
  padding: 0.7rem 1rem;
  cursor: pointer;
  text-align: left;
  transition: all var(--transition);
}
.country-option:hover,
.country-option.active { background: var(--bg-raised); color: white; }
.country-option.active { color: var(--red); }

@media (max-width: 768px) {
  .footer-top { grid-template-columns: 1fr; gap: 2rem; }
  .footer-nav-cols { grid-template-columns: repeat(2, 1fr); }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 1rem; }
}
@media (max-width: 480px) {
  .footer-nav-cols { grid-template-columns: 1fr; }
}

/* ── Divider ── */
.divider {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--border-light), transparent);
  margin: 0;
}

/* ── Red accent line ── */
