.nav-logo {
  font-family: var(--font-head);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: white;
  text-decoration: none;
  flex-shrink: 0;
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  list-style: none;
  gap: 0;
  margin-left: 1rem;
  flex: 1;
}
.nav-link {
  font-family: var(--font-head);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 0.5rem 0.85rem;
  transition: color var(--transition);
  white-space: nowrap;
  position: relative;
}
.nav-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0.85rem;
  right: 0.85rem;
  height: 2px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-link:hover { color: white; }
.nav-link:hover::after,
.nav-link.active::after { transform: scaleX(1); }
.nav-link.active { color: white; }
.nav-actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-shrink: 0;
}
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: white;
  transition: all var(--transition);
}

@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-actions { display: none; }
  .nav-toggle { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: calc(var(--nav-height) + 36px);
    left: 0; right: 0;
    background: oklch(6% 0.01 0 / 0.98);
    border-bottom: 1px solid var(--border);
    padding: 1.5rem 2rem 2rem;
    gap: 0.25rem;
  }
  .nav-links.open + .nav-actions {
    display: flex;
    position: fixed;
    bottom: 0; left: 0; right: 0;
    padding: 1rem 2rem;
    background: oklch(6% 0.01 0);
    border-top: 1px solid var(--border);
    justify-content: center;
    gap: 1rem;
  }
