.page-hero {
  padding: 7rem 2rem 5rem;
  text-align: center;
  background: oklch(8% 0.01 0);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 60% at 50% 30%, oklch(30% 0.22 25 / 0.14) 0%, transparent 65%);
  pointer-events: none;
}
.page-hero-inner { position: relative; z-index: 1; }
.page-hero .section-label { display: block; margin-bottom: 1.5rem; }
.page-hero h1 { font-size: clamp(2.5rem, 7vw, 6rem); margin-bottom: 1.5rem; }
.page-hero p {
